#!/usr/bin/env node
'use strict';

/**
 * P0-7: build outputs must not be tracked.
 *
 * `dist/` and `examples/cloud-ide/public/dist/` are generated by
 * `tools/bundle.js`. Keeping them in git caused merge conflicts, stale
 * artifacts, and a false sense that a clean clone had a working build.
 *
 * This suite fails if either directory is tracked, unignored, or if CI stops
 * rebuilding and verifying reproducibility.
 */

const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const GENERATED_DIRS = ['dist', 'examples/cloud-ide/public/dist'];

let passed = 0;
const failures = [];

function test(name, fn) {
  try {
    fn();
    passed++;
    console.log(`  ✓ ${name}`);
  } catch (err) {
    failures.push({ name, err });
    console.log(`  ✗ ${name}`);
    console.log(`    ${err.message}`);
  }
}

function read(rel) {
  return fs.readFileSync(path.join(ROOT, rel), 'utf8');
}

function git(args) {
  return execFileSync('git', args, { cwd: ROOT, encoding: 'utf8' }).trim();
}

console.log('\n════════════════════════════════════════════════════════════════════════════');
console.log('   P0-7: Build Outputs Are Not Tracked');
console.log('════════════════════════════════════════════════════════════════════════════\n');

test('generated directories are ignored', () => {
  const ignore = read('.gitignore');
  for (const dir of GENERATED_DIRS) {
    assert.ok(ignore.includes(`${dir}/`), `.gitignore is missing ${dir}/`);
  }
});

test('git tracks no files under the generated directories', () => {
  let tracked = '';
  try {
    tracked = git(['ls-files', '--', ...GENERATED_DIRS]);
  } catch (err) {
    assert.fail(`git ls-files failed: ${err.message}`);
  }
  assert.equal(tracked, '', `generated files are still tracked:\n${tracked}`);
});

test('git ignores representative build outputs', () => {
  for (const file of ['dist/code-lab.js', 'dist/code-lab.d.ts', 'examples/cloud-ide/public/dist/code-lab.js']) {
    assert.doesNotThrow(() => git(['check-ignore', '-q', '--', file]), `${file} is not ignored`);
  }
});

test('build outputs still exist locally after untracking', () => {
  for (const file of [
    'dist/code-lab.js',
    'dist/code-lab.d.ts',
    'dist/code-lab.css',
    'examples/cloud-ide/public/dist/code-lab.js'
  ]) {
    assert.ok(fs.existsSync(path.join(ROOT, file)), `${file} is missing; run bun run build`);
  }
});

test('the package still ships dist after a build', () => {
  const pkg = JSON.parse(read('package.json'));
  assert.ok(pkg.files.includes('dist'), 'package.json#files must include dist');
  assert.ok(
    pkg.scripts.test.includes('tools/bundle.js'),
    'the test script must build before reading dist'
  );
});

test('CI rebuilds and compares hashes instead of tracked artifacts', () => {
  const ci = read('.github/workflows/ci.yml');
  assert.ok(ci.includes('bun run build'), 'CI must build the package');
  assert.ok(ci.includes('sha256sum'), 'CI must hash the generated files');
  assert.ok(
    ci.includes('diff -u /tmp/build-first.sha /tmp/build-second.sha'),
    'CI must compare two clean builds'
  );
  assert.ok(
    !ci.includes('git diff --exit-code -- dist'),
    'CI still compares generated files against git'
  );
});

console.log('\n════════════════════════════════════════════════════════════════════════════');
console.log(`P0-7 Untracked Build Suite Complete: ${passed} passed, ${failures.length} failed`);
console.log('════════════════════════════════════════════════════════════════════════════\n');

if (failures.length > 0) {
  for (const failure of failures) {
    console.error(`\n[${failure.name}]`);
    console.error(failure.err.stack || failure.err.message);
  }
  process.exit(1);
}
